INSERT INTO "news_sources" ("kind", "feed_url", "display_name", "site_url", "notes", "enabled") VALUES
  ('rss', 'https://news.google.com/rss/search?q=%28%D8%B9%D9%82%D8%A7%D8%B1%20OR%20%D8%A7%D9%84%D8%B9%D9%82%D8%A7%D8%B1%D9%8A%20OR%20%D8%A7%D9%84%D8%B9%D9%82%D8%A7%D8%B1%D8%A7%D8%AA%29%20%D8%A7%D9%84%D8%B3%D8%B9%D9%88%D8%AF%D9%8A%D8%A9%20when%3A7d&hl=ar&gl=SA&ceid=SA:ar', 'أخبار جوجل: عقار السعودية', 'https://news.google.com', 'Google News: Saudi real estate (AR) — Broad Arabic net: any Saudi story mentioning عقار/العقاري/العقارات in the last 7 days, across all Saudi and Gulf outlets (Okaz, Al Riyadh, Al Jazirah, Maaal, Al Arabiya...). High recall, needs the filter.', true),
  ('rss', 'https://news.google.com/rss/search?q=%28%22%D8%A7%D9%84%D9%87%D9%8A%D8%A6%D8%A9%20%D8%A7%D9%84%D8%B9%D8%A7%D9%85%D8%A9%20%D9%84%D9%84%D8%B9%D9%82%D8%A7%D8%B1%22%20OR%20%22%D9%87%D9%8A%D8%A6%D8%A9%20%D8%A7%D9%84%D8%B9%D9%82%D8%A7%D8%B1%22%20OR%20%22%D8%A7%D9%84%D8%B3%D8%AC%D9%84%20%D8%A7%D9%84%D8%B9%D9%82%D8%A7%D8%B1%D9%8A%22%20OR%20%22%D8%A7%D9%84%D9%88%D8%B3%D8%A7%D8%B7%D8%A9%20%D8%A7%D9%84%D8%B9%D9%82%D8%A7%D8%B1%D9%8A%D8%A9%22%29%20when%3A7d&hl=ar&gl=SA&ceid=SA:ar', 'أخبار جوجل: الهيئة العامة للعقار', 'https://news.google.com', 'Google News: REGA & Registry (AR) — Regulator-focused: REGA, the Real Estate Registry and brokerage rules. Highest-value regulation stories; covers SPA, Sabq, Al Jazirah, Maaal which block direct RSS.', true),
  ('rss', 'https://news.google.com/rss/search?q=%28%22%D9%85%D9%86%D8%B5%D8%A9%20%D8%A5%D9%8A%D8%AC%D8%A7%D8%B1%22%20OR%20%22%D8%B9%D9%82%D9%88%D8%AF%20%D8%A7%D9%84%D8%A5%D9%8A%D8%AC%D8%A7%D8%B1%22%20OR%20%22%D8%A7%D9%84%D8%A5%D9%8A%D8%AC%D8%A7%D8%B1%D8%A7%D8%AA%20%D8%A7%D9%84%D8%B3%D9%83%D9%86%D9%8A%D8%A9%22%20OR%20%22%D8%AA%D8%AB%D8%A8%D9%8A%D8%AA%20%D8%A7%D9%84%D8%A5%D9%8A%D8%AC%D8%A7%D8%B1%22%20OR%20%22%D8%B2%D9%8A%D8%A7%D8%AF%D8%A9%20%D8%A7%D9%84%D8%A5%D9%8A%D8%AC%D8%A7%D8%B1%22%20OR%20%22%D8%A7%D9%84%D8%B9%D9%84%D8%A7%D9%82%D8%A9%20%D8%A7%D9%84%D8%A5%D9%8A%D8%AC%D8%A7%D8%B1%D9%8A%D8%A9%22%29%20%28%D8%A7%D9%84%D8%B3%D8%B9%D9%88%D8%AF%D9%8A%D8%A9%20OR%20%D8%A7%D9%84%D8%B1%D9%8A%D8%A7%D8%B6%20OR%20%D8%AC%D8%AF%D8%A9%20OR%20%D8%A7%D9%84%D9%85%D9%85%D9%84%D9%83%D8%A9%29%20when%3A14d&hl=ar&gl=SA&ceid=SA:ar', 'أخبار جوجل: الإيجار والتأجير', 'https://news.google.com', 'Google News: rent & Ejar (AR) — Rent freeze, Ejar platform, lease contracts, landlord-tenant relation, restricted to Saudi place names. Still pulls Egyptian old-rent-law stories, which the foreign-geo rule drops.', true),
  ('rss', 'https://news.google.com/rss/search?q=%28%22%D8%B1%D8%B3%D9%88%D9%85%20%D8%A7%D9%84%D8%A3%D8%B1%D8%A7%D8%B6%D9%8A%20%D8%A7%D9%84%D8%A8%D9%8A%D8%B6%D8%A7%D8%A1%22%20OR%20%22%D8%A7%D9%84%D8%B9%D9%82%D8%A7%D8%B1%D8%A7%D8%AA%20%D8%A7%D9%84%D8%B4%D8%A7%D8%BA%D8%B1%D8%A9%22%20OR%20%22%D8%B6%D8%B1%D9%8A%D8%A8%D8%A9%20%D8%A7%D9%84%D8%AA%D8%B5%D8%B1%D9%81%D8%A7%D8%AA%20%D8%A7%D9%84%D8%B9%D9%82%D8%A7%D8%B1%D9%8A%D8%A9%22%20OR%20%22%D8%A7%D9%84%D8%AA%D8%B5%D8%B1%D9%81%D8%A7%D8%AA%20%D8%A7%D9%84%D8%B9%D9%82%D8%A7%D8%B1%D9%8A%D8%A9%22%29%20%28%D8%A7%D9%84%D8%B3%D8%B9%D9%88%D8%AF%D9%8A%D8%A9%20OR%20%D8%A7%D9%84%D9%85%D9%85%D9%84%D9%83%D8%A9%20OR%20%D8%A7%D9%84%D8%B1%D9%8A%D8%A7%D8%B6%29%20when%3A14d&hl=ar&gl=SA&ceid=SA:ar', 'أخبار جوجل: الأراضي البيضاء والتصرفات العقارية', 'https://news.google.com', 'Google News: white land, vacant property & RETT (AR) — Fees and taxes that change landlord costs: white-land fees, vacant-property fee, real-estate transaction tax, transactions restricted to the Registry.', true),
  ('rss', 'https://news.google.com/rss/search?q=%28%22%D8%A7%D9%84%D8%AA%D9%85%D9%88%D9%8A%D9%84%20%D8%A7%D9%84%D8%B9%D9%82%D8%A7%D8%B1%D9%8A%22%20OR%20%22%D8%B5%D9%86%D8%AF%D9%88%D9%82%20%D8%A7%D9%84%D8%AA%D9%86%D9%85%D9%8A%D8%A9%20%D8%A7%D9%84%D8%B9%D9%82%D8%A7%D8%B1%D9%8A%D8%A9%22%20OR%20%22%D8%A7%D9%84%D8%B5%D9%86%D8%AF%D9%88%D9%82%20%D8%A7%D9%84%D8%B9%D9%82%D8%A7%D8%B1%D9%8A%22%20OR%20%22%D8%A7%D9%84%D8%AF%D8%B9%D9%85%20%D8%A7%D9%84%D8%B3%D9%83%D9%86%D9%8A%22%20OR%20%22%D8%B3%D9%83%D9%86%D9%8A%22%20OR%20%22%D8%A7%D9%84%D8%B4%D8%B1%D9%83%D8%A9%20%D8%A7%D9%84%D8%B3%D8%B9%D9%88%D8%AF%D9%8A%D8%A9%20%D9%84%D8%A5%D8%B9%D8%A7%D8%AF%D8%A9%20%D8%A7%D9%84%D8%AA%D9%85%D9%88%D9%8A%D9%84%20%D8%A7%D9%84%D8%B9%D9%82%D8%A7%D8%B1%D9%8A%22%29%20%D8%A7%D9%84%D8%B3%D8%B9%D9%88%D8%AF%D9%8A%D8%A9%20when%3A7d&hl=ar&gl=SA&ceid=SA:ar', 'أخبار جوجل: التمويل العقاري وسكني', 'https://news.google.com', 'Google News: mortgage, REDF & Sakani (AR) — Mortgage and subsidy: REDF monthly deposits, Sakani, SRC, bank mortgage volumes.', true),
  ('rss', 'https://news.google.com/rss/search?q=site%3Aargaam.com%20%28%D8%B9%D9%82%D8%A7%D8%B1%20OR%20%D8%A7%D9%84%D8%B9%D9%82%D8%A7%D8%B1%D9%8A%20OR%20%D8%A7%D9%84%D8%B9%D9%82%D8%A7%D8%B1%D9%8A%D8%A9%20OR%20%D8%A7%D9%84%D8%A5%D9%8A%D8%AC%D8%A7%D8%B1%D8%A7%D8%AA%20OR%20%D8%A7%D9%84%D8%A5%D8%B3%D9%83%D8%A7%D9%86%29%20when%3A7d&hl=ar&gl=SA&ceid=SA:ar', 'أرقام: العقار (عبر أخبار جوجل)', 'https://www.argaam.com', 'Argaam real estate (via Google News) — Argaam blocks direct RSS (403). This site: query is the only free way to get its real-estate and REIT disclosures. Also returns Gulf items and company index pages, which the filter drops.', true),
  ('rss', 'https://news.google.com/rss/search?q=site%3Aaleqt.com%20%28%D8%B9%D9%82%D8%A7%D8%B1%20OR%20%D8%A7%D9%84%D8%B9%D9%82%D8%A7%D8%B1%D9%8A%20OR%20%D8%A7%D9%84%D8%B9%D9%82%D8%A7%D8%B1%D9%8A%D8%A9%20OR%20%D8%A7%D9%84%D8%A5%D9%8A%D8%AC%D8%A7%D8%B1%D8%A7%D8%AA%20OR%20%D8%A7%D9%84%D8%A5%D8%B3%D9%83%D8%A7%D9%86%29%20when%3A7d&hl=ar&gl=SA&ceid=SA:ar', 'الاقتصادية: العقار (عبر أخبار جوجل)', 'https://www.aleqt.com', 'Al Eqtisadiah real estate (via Google News) — Aleqt has no working RSS (404). Saudi business daily with rent-inflation and market analysis pieces.', true),
  ('rss', 'https://news.google.com/rss/search?q=site%3Aspa.gov.sa%20%28%D8%A7%D9%84%D8%B9%D9%82%D8%A7%D8%B1%20OR%20%D8%A7%D9%84%D8%A5%D8%B3%D9%83%D8%A7%D9%86%20OR%20%D8%A7%D9%84%D8%A5%D9%8A%D8%AC%D8%A7%D8%B1%20OR%20%22%D8%A7%D9%84%D8%A3%D8%B1%D8%A7%D8%B6%D9%8A%20%D8%A7%D9%84%D8%A8%D9%8A%D8%B6%D8%A7%D8%A1%22%20OR%20%22%D8%A7%D9%84%D8%B3%D8%AC%D9%84%20%D8%A7%D9%84%D8%B9%D9%82%D8%A7%D8%B1%D9%8A%22%29%20when%3A14d&hl=ar&gl=SA&ceid=SA:ar', 'واس: العقار والإسكان (عبر أخبار جوجل)', 'https://www.spa.gov.sa', 'SPA real estate & housing (via Google News) — Official announcements (REGA, Registry, REDF, MOMAH) straight from the Saudi Press Agency, whose own RSS returns HTML. Includes protocol news (emir receives...), which the filter drops.', true),
  ('rss', 'https://news.google.com/rss/search?q=site%3Aalarabiya.net%20%28%D8%A7%D9%84%D8%B9%D9%82%D8%A7%D8%B1%20OR%20%D8%A7%D9%84%D8%B9%D9%82%D8%A7%D8%B1%D8%A7%D8%AA%20OR%20%D8%A7%D9%84%D8%A5%D9%8A%D8%AC%D8%A7%D8%B1%D8%A7%D8%AA%20OR%20%D8%A7%D9%84%D8%A5%D8%B3%D9%83%D8%A7%D9%86%29%20%D8%A7%D9%84%D8%B3%D8%B9%D9%88%D8%AF%D9%8A%D8%A9%20when%3A7d&hl=ar&gl=SA&ceid=SA:ar', 'العربية: العقار (عبر أخبار جوجل)', 'https://www.alarabiya.net', 'Al Arabiya real estate (via Google News) — Al Arabiya Aswaq blocks direct RSS (403). Good Saudi real-estate coverage, plus a lot of Gulf/global property news that the foreign-geo rule removes.', true),
  ('rss', 'https://news.google.com/rss/search?q=Saudi%20%28%22real%20estate%22%20OR%20housing%20OR%20mortgage%20OR%20rents%29%20when%3A7d&hl=en-SA&gl=SA&ceid=SA:en', 'أخبار جوجل: العقار السعودي (إنجليزي)', 'https://news.google.com', 'Google News: Saudi real estate (EN) — English net: Saudi real estate, housing, mortgage, rents (Arab News, Arabian Business, TradeArabia, Zawya). Many syndicated duplicates, which near-dup dedupe absorbs.', true),
  ('rss', 'https://news.google.com/rss/search?q=Saudi%20%28%22Real%20Estate%20General%20Authority%22%20OR%20%22white%20land%22%20OR%20%22Real%20Estate%20Registry%22%20OR%20%22rent%20freeze%22%20OR%20Ejar%20OR%20REDF%20OR%20%22Real%20Estate%20Refinance%22%29%20when%3A14d&hl=en-SA&gl=SA&ceid=SA:en', 'أخبار جوجل: سياسات العقار السعودية (إنجليزي)', 'https://news.google.com', 'Google News: Saudi property policy (EN) — English policy terms: REGA, white land, Real Estate Registry, rent freeze, Ejar, REDF, SRC. Low volume, high precision.', true),
  ('rss', 'https://news.google.com/rss/search?q=site%3Aargaam.com/en%20%28%22real%20estate%22%20OR%20housing%20OR%20mortgage%20OR%20rent%20OR%20REIT%29%20when%3A14d&hl=en-SA&gl=SA&ceid=SA:en', 'أرقام إنجليزي: العقار (عبر أخبار جوجل)', 'https://www.argaam.com/en', 'Argaam English real estate (via Google News) — Argaam English: REGA decisions, monthly transaction totals, REIT disclosures. REIT stock-move noise stays below threshold.', true),
  ('rss', 'https://www.alyaum.com/rssFeed/1006/99', 'اليوم: عقارات', 'https://www.alyaum.com', 'Alyaum: Real estate — A dedicated real-estate section feed from a Saudi daily (Dammam). Almost all items are on topic (Registry, Sakani deposits, white land, mortgage volumes), and it has real descriptions.', true),
  ('rss', 'https://www.okaz.com.sa/rssFeed/4', 'عكاظ: اقتصاد', 'https://www.okaz.com.sa', 'Okaz: Economy — Okaz economy section, the only Okaz feed with business news. Real-estate yield is low (mostly oil, gold, stocks), so the filter keeps a few items a week. Optional.', true),
  ('rss', 'https://www.al-madina.com/rssFeed/79', 'المدينة: اقتصاد', 'https://www.al-madina.com', 'Al Madina: Economy — Al Madina economy section. It carries REGA and Registry announcements the same day, with low real-estate yield otherwise. Optional.', true)
